import { useCallback, useEffect, useState } from 'react'
import './App.css'

const API = import.meta.env.VITE_API_URL || 'http://127.0.0.1:5000'
const readToken = () => localStorage.getItem('parkzen-token')
async function api(path, options = {}) {
  const headers = { ...(options.body instanceof FormData ? {} : { 'Content-Type': 'application/json' }), ...(options.headers || {}) }
  if (readToken()) headers.Authorization = `Bearer ${readToken()}`
  const response = await fetch(`${API}${path}`, { ...options, headers })
  const data = await response.json().catch(() => ({}))
  if (!response.ok) throw new Error(data.error || 'Something went wrong. Please try again.')
  return data
}
const mapsUrl = (d) => `https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(`${d.latitude},${d.longitude} (${d.name}, ${d.address})`)}&travelmode=driving`
const timeAgo = (date) => {
  if (!date) return 'No confirmed update yet'
  const mins = Math.max(0, Math.floor((Date.now() - new Date(date).getTime()) / 60000))
  return mins < 1 ? 'Updated just now' : mins < 60 ? `Updated ${mins} minute${mins === 1 ? '' : 's'} ago` : `Updated ${Math.floor(mins / 60)} hour${Math.floor(mins / 60) === 1 ? '' : 's'} ago`
}
const localDate = (date = new Date()) => new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Kolkata', year: 'numeric', month: '2-digit', day: '2-digit' }).format(date)
const timeLabel = (hour, minute) => new Date(Date.UTC(2020, 0, 1, hour, minute)).toLocaleTimeString('en-IN', { timeZone: 'UTC', hour: 'numeric', minute: '2-digit', hour12: true })
const toKolkataISO = (date, time) => `${date}T${time}:00+05:30`
const addDate = (date, days) => { const value = new Date(`${date}T12:00:00+05:30`); value.setUTCDate(value.getUTCDate() + days); return localDate(value) }
const displayDateTime = (value) => { if (!value) return ''; const parts = Object.fromEntries(new Intl.DateTimeFormat('en-IN', { timeZone: 'Asia/Kolkata', day: '2-digit', month: '2-digit', year: 'numeric', hour: 'numeric', minute: '2-digit', hour12: true }).formatToParts(new Date(value)).map(part => [part.type, part.value])); return `${parts.day}-${parts.month}-${parts.year}, ${parts.hour}:${parts.minute} ${parts.dayPeriod.toUpperCase()}` }
const moneyFromPaise = (paise, currency = 'INR') => new Intl.NumberFormat('en-IN', { style: 'currency', currency, minimumFractionDigits: 2, maximumFractionDigits: 2 }).format((Number(paise) || 0) / 100)
const bookingRatePaise = booking => Number(booking.rate_per_block_paise) || Math.round((Number(booking.rate_per_block) || 0) * 100)
const bookingTotalPaise = booking => Number(booking.total_amount_paise) || Math.round((Number(booking.total_amount) || 0) * 100)
const bookingDiscountPaise = booking => booking.discount_amount_paise != null ? Number(booking.discount_amount_paise) : 0
const bookingBaseRatePaise = booking => booking.base_rate_per_block != null ? Math.round(Number(booking.base_rate_per_block) * 100) : Math.round((Number(booking.rate_per_block) || 0) * 100)
const defaultBookingForm = { vehicle_type: 'car', start_date: localDate(), start_time: '', end_timestamp: '', payment_method: 'upi' }
function Status({ item }) {
  const a = item.availability
  if (!a) return <span className="pz-status muted">Awaiting first update</span>
  const level = a.available === 0 ? 'full' : a.available / Math.max(a.total, 1) <= .2 ? 'limited' : 'open'
  const label = level === 'full' ? 'Parking full' : level === 'limited' ? 'Limited parking' : 'Parking available'
  return <span className={`pz-status ${level}`}>{label}</span>
}

