      {!manager && item.final_penalty > 0 && item.penalty_payment_status === 'paid' && <div className="pz-overstay-evidence"><b>Penalty receipt</b><span>{item.booking_code} · {item.level_name} · {item.slot_number}</span><span>{item.duration_minutes} billable minutes × ₹{item.rate_per_minute}/min = ₹{item.final_penalty}</span><span>Paid · Transaction {item.penalty_payment_reference || 'verified'}</span></div>}
      {!manager && item.final_penalty === 0 && item.departure_detected_at && <p>No penalty due.</p>}
